<script setup lang="ts">
import { ref } from 'vue'
import { onLoad, onShow, onHide, onUnload } from '@dcloudio/uni-app'
import AppCard from '../../components/AppCard.vue'
import { consultationRepository as api } from '../../services/api/consultation'
import type { ConsultationRequestV2 } from '../../types/consultation'
import { uniApi as uni } from '../../services/platform/uni'
const requestId = ref(''); const item = ref<ConsultationRequestV2>(); const error = ref(''); let timer: ReturnType<typeof setInterval> | undefined
async function load() { try { const items = await api.consultationRequests(); item.value = items.find(entry => entry.id === requestId.value) || items[0]; if (item.value?.conversationId) uni.redirectTo({ url: `/pages/consultation/index?conversationId=${item.value.conversationId}` }); error.value = '' } catch (e) { error.value = (e as Error).message } }
function stop() { if (timer) clearInterval(timer); timer = undefined }
onLoad(options => { requestId.value = options?.requestId || '' }); onShow(() => { load(); stop(); timer = setInterval(load, 4000) }); onHide(stop); onUnload(stop)
</script>
<template><view class="page waiting-page"><view class="waiting-hero"><view class="pulse"><view class="pulse-dot" /></view><text class="title">正在为你匹配</text><text class="subtitle">平台会根据服务状态与专业方向安排健康管理师</text></view><AppCard v-if="error" class="error"><text class="danger">{{ error }}</text><button class="retry" @click="load">重新加载</button></AppCard><AppCard class="progress-card"><view class="step active"><view class="step-dot">1</view><view><text class="step-title">已提交咨询请求</text><text class="muted">{{ item ? new Date(item.createdAt).toLocaleString('zh-CN') : '正在提交' }}</text></view></view><view class="line" /><view class="step" :class="{ active: item?.status === 'assigned' || item?.status === 'in_progress' }"><view class="step-dot">2</view><view><text class="step-title">等待健管师确认</text><text class="muted">配对成功后会立即通知你</text></view></view><view class="line" /><view class="step" :class="{ active: item?.status === 'in_progress' }"><view class="step-dot">3</view><view><text class="step-title">进入咨询房间</text><text class="muted">支持文字沟通与 Mock 语音</text></view></view></AppCard><button class="btn secondary" @click="uni.navigateBack()">返回咨询入口</button></view></template>
<style scoped>.waiting-page{padding-top:54rpx;background:#fffaf6}.waiting-hero{text-align:center;padding:20rpx 20rpx 36rpx}.pulse{display:flex;align-items:center;justify-content:center;width:150rpx;height:150rpx;margin:0 auto 26rpx;border-radius:50%;background:#fff0e5;box-shadow:0 0 0 20rpx #fff7f1,0 0 0 40rpx #fffbf8}.pulse-dot{width:62rpx;height:62rpx;border-radius:50%;background:linear-gradient(145deg,#e68a4d,#c95c28);box-shadow:0 0 0 13rpx rgba(217,107,43,.16)}.waiting-hero .title{display:block;color:#2a201c;font-size:38rpx;font-weight:800}.waiting-hero .subtitle{display:block;max-width:510rpx;margin:14rpx auto 0;line-height:1.6}.error{padding:20rpx;background:#fff0ed}.error .danger{display:block}.retry{width:100%;height:64rpx;margin-top:14rpx;line-height:64rpx;color:#c8652a;background:#fff}.progress-card{padding:30rpx 26rpx}.step{display:flex;align-items:center;opacity:.45}.step.active{opacity:1}.step-dot{display:flex;align-items:center;justify-content:center;flex:0 0 46rpx;width:46rpx;height:46rpx;margin-right:18rpx;border-radius:50%;color:#fff;background:#cfc6c0;font-size:22rpx;font-weight:800}.active .step-dot{background:#d96b2b}.step-title{display:block;color:#44332b;font-size:25rpx;font-weight:800}.step .muted{margin-top:5rpx}.line{width:2rpx;height:48rpx;margin:0 0 0 22rpx;background:#eaded6}.btn{margin-top:24rpx}</style>
